import mpmath as mp
mp.mp.dps=80

def H(m):
    return mp.harmonic(m) if hasattr(mp,'harmonic') else sum(mp.mpf(1)/j for j in range(1,m+1))
# mpmath has harmonic? let's implement
def harm(m):
    return mp.nsum(lambda j: 1/j, [1, m]) if False else sum(mp.mpf(1)/j for j in range(1,m+1))

def g_series(alpha, terms=200000):
    alpha=mp.mpf(alpha)
    x=alpha/(1+alpha)**2
    # sum terms recursively for stability
    # C_k and H_2k
    C=mp.mpf(1); H=mp.mpf(0); sC=mp.mpf(0); sH=mp.mpf(0)
    for k in range(terms):
        if k==0:
            C=mp.mpf(1); H=mp.mpf(0)
        else:
            C= C*mp.mpf(2)*(2*k-1)/(k+1) # C_k from C_{k-1}: C_k=C_{k-1}*2(2k-1)/(k+1)
            H=H + mp.mpf(1)/(2*k-1)+mp.mpf(1)/(2*k) # H_{2k} from H_{2k-2}
        term=C*x**k
        sC += term
        sH += term*H
        if k>20 and abs(term) < mp.mpf('1e-70')*max(mp.mpf(1),abs(sC)):
            break
    return (mp.log(1+alpha)*sC - sH)/(1+alpha), sC/(1+alpha), lenH if False else None

def f(n, alpha):
    alpha=mp.mpf(alpha); n=mp.mpf(n)
    z=4*alpha/(1+alpha)**2
    return (1+alpha)**(n-1)*mp.hyper([ (1-n)/2, 1-n/2],[2], z)

def g_num(alpha):
    h=mp.mpf('1e-40')
    # use high order finite difference? derivative at n=0 complex n real direction
    return (f(h,alpha)-f(-h,alpha))/(2*h)

for a in [0, mp.mpf('0.0001'), mp.mpf('0.01'), mp.mpf('0.1'), mp.mpf('0.25'), mp.mpf('0.5'), mp.mpf('0.75'), mp.mpf('0.9'), mp.mpf('1')]:
    gs=g_series(a, terms=10000)
    gn=g_num(a)
    print('alpha', mp.nstr(a,10), 'g_series', mp.nstr(gs,30), 'g_num', mp.nstr(gn,30))
    print(' candidate ln1pa', mp.nstr(mp.log(1+a),30), ' candidate? ', mp.nstr(gn/mp.log(1+a) if a"'!=0 else mp.nan,30))
