import mpmath as mp
mp.mp.dps=50

def R(g,z):
 b=mp.mpf(1)-g; zp=g+b*z
 return b*(mp.atanh(zp)/zp)/(mp.atanh(z)/z)
def dR(g,z):
 return mp.diff(lambda x:R(g,x),z)
for g in [mp.mpf(1)/8,mp.mpf(1)/4,mp.mpf(1)/2]:
 z=mp.findroot(lambda x:dR(g,x), mp.mpf('.78'))
 val=R(g,z)
 print('g',g,'z',mp.nstr(z,40),'val',mp.nstr(val,40))
 for K in range(2,200):
  a=mp.pslq([val, mp.mpf(1), mp.log(K)], tol=mp.mpf('1e-35'), maxcoeff=10**8)
  if a:
   print(' relation',a,'K',K);break
