import numpy as np
from scipy.linalg import eigvalsh
from scipy.optimize import differential_evolution
I=np.eye(2); sx=np.array([[0,1],[1,0]],complex); sy=np.array([[0,-1j],[1j,0]],complex); sz=np.array([[1,0],[0,-1]],complex); ps=[sx,sy,sz]
def M(s):
 sig=(I+sum(s[i]*ps[i] for i in range(3)))/2
 vals,U=np.linalg.eigh(sig); out=np.zeros((3,3))
 for a in range(3):
  for b in range(3):
   X=U.conj().T@(ps[a]/2)@U; Y=U.conj().T@(ps[b]/2)@U
   for i in range(2):
    for j in range(2):
     w=1/vals[i] if abs(vals[i]-vals[j])<1e-11 else (np.log(vals[i])-np.log(vals[j]))/(vals[i]-vals[j])
     out[a,b]+=np.conj(X[i,j])*w*Y[i,j]
 return out.real
def eta(g,v):
 x,y,z=v; s=np.array([x,y,z]); sp=np.array([np.sqrt(1-g)*x,np.sqrt(1-g)*y,(1-g)*z+g])
 L=np.diag([np.sqrt(1-g)]*2+[1-g])
 return eigvalsh(L@M(sp)@L,M(s))[-1]
for g in [.125,.25,.5]:
 def obj(v):
  if np.dot(v,v)>=.999999: return 1
  return -eta(g,v)
 r=differential_evolution(obj,[(0,.999999),(-.999999,.999999),(-.999999,.999999)],seed=4,tol=1e-9,popsize=20)
 print(g,-r.fun,r.x)
PY
