/bin/bash -c "python3 - <<'PY'
import itertools
import sympy as sp

I=sp.I
X=sp.Matrix([[0,1],[1,0]])
Y=sp.Matrix([[0,-I],[I,0]])
Z=sp.Matrix([[1,0],[0,-1]])
Id=sp.eye(2)
paulis=[X,Y,Z]

def kron_all(ms):
    out=sp.Matrix([[1]])
    for m in ms:
        out=sp.kronecker_product(out,m)
    return out

def op_on(pauli_ops):
    return kron_all([pauli_ops.get(i,Id) for i in range(4)])

T={}
for pair in [(0,1),(2,3)]:
    a,b=pair
    T[pair]=sum((op_on({a:P,b:P}) for P in paulis), sp.zeros(16))/3

ops=[]
for P in paulis:
    ops.append(op_on({0:P,1:P,2:P,3:P}))
pairs=[((0,1),(2,3)),((0,2),(1,3)),((0,3),(1,2))]
for A in paulis:
    for B in paulis:
        if A is B: continue
        for p,q in pairs:
            ops.append(op_on({p[0]:A,p[1]:A,q[0]:B,q[1]:B}))
T4=sum(ops, sp.zeros(16))/15
N=(sp.eye(16)+T[(0,1)]+T[(2,3)]+T4)/4
print('Hermitian',N==N.H)
print('trace N',sp.trace(N))
print('eigs',N.eigenvals())
Nd={}
for r in range(16):
    for c in range(16):
        if N[r,c]"'!=0:
            Nd[(r,c)]=sp.simplify(N[r,c])
print('"'sparse N',len(Nd))

total=sp.Rational(0)
terms=[]
for ket_copy in itertools.product([0,1], repeat=4):
    row_ket=tuple(ket_copy[c] for c in range(4))
    kr=sum(row_ket[j]<<(3-j) for j in range(4))
    for bra_copy in itertools.product([0,1], repeat=4):
        row_bra=tuple(bra_copy[c] for c in range(4))
        br=sum(row_bra[j]<<(3-j) for j in range(4))
        prod=sp.Rational(1)
        for row in range(3):
            prod*=Nd.get((kr,br),0)
        val=sp.simplify(prod/16)
        if val:
            terms.append((ket_copy,bra_copy,val))
            total+=val
print('nonzero terms',len(terms))
print('total',sp.simplify(total),float(total))
for t in terms:
    print(t)
PY"

