from sympy import Rational, simplify, I

x,a=Rational(1,4),Rational(1,12)
b=Rational(1,60)

def parity(perm):
    inv=0
    for i in range(4):
      for j in range(i+1,4):
        inv += perm[i]>perm[j]
    return 1 if inv%2==0 else -1

distinct=set(permutations(range(4)))
print('4"'! unique'"',len(distinct))
# N as permutation indices
N={p: parity(p)*(x if len(set(p))==2 else b) for p in distinct}
