import numpy as np
from scipy.optimize import brentq, minimize_scalar


def Mdet(k, R):
    if k <= 0 or R <= k*k:
        return np.nan
    a = np.sqrt(k*k + k*np.sqrt(R))
    b = np.sqrt(k*np.sqrt(R) - k*k)
    m11 = a*np.cosh(a) + a*np.cos(b)
    m12 = np.sinh(a) - (a/b)*np.sin(b)
    m21 = a*np.sinh(a) + b*np.sin(b)
    m22 = np.cosh(a) - np.cos(b)
    return m11*m22 - m12*m21

def crit_R(k, lo=None, hi=None):
    # find first determinant root at fixed k. Start low and expand.
    if lo is None:
        lo = k*k + 1e-8
    if hi is None: hi = lo + 1
    f0=Mdet(k,lo)
    # root must be bracketed; walk upward
    x0=lo
    for _ in range(200):
        x1=hi
        f0=Mdet(k,x0); f1=Mdet(k,x1)
        if np.isfinite(f0) and np.isfinite(f1) and f0*f1 <= 0:
            return brentq(lambda R: Mdet(k,R), x0, x1, xtol=1e-14, rtol=1e-13)
        x0=x1
        hi=x1 + max(1.0, (x1-lo)*1.5)
    raise RuntimeError('no root')

def scan():
    for k in [0.1,0.2,0.5,1,1.5,2,2.2,2.5,3,4,5]:
        try: print(k, crit_R(k))
        except Exception as e: print('fail', k, e)

if __name__=='__main__':
    scan()
